Set(Handle aHandle, long growth = 1);	void AdjustHandleSize();				// adjust handle to actual size of stream	void AdjustStreamSize();				// sets stream size to actual handle size.	TStream* GetStream();					// accessor function	operator Handle();						// coersion operator	operator TStream*();					// coersion operator	void Cleanup();	static void CallCleanup(void* context);};//----------------------------------------------------------------------------------------// CPermAllocator//----------------------------------------------------------------------------------------class CPermAllocator{protected:	bool		 	fOldPerm;	FailInfo		fFailInfo;public:	CPermAllocator(bool newPerm);	~CPermAllocator();	void Cleanup();	static void CallCleanup(void* context);};//----------------------------------------------------------------------------------------// inline implementations//----------------------------------------------------------------------------------------inline CTemporaryFileStream::operator TStream*(){	return fStream;}//----------------------------------------------------------------------------------------inline long CTemporaryCountingStream::GetBytesNeeded(){	return fStream->GetPosition();}//----------------------------------------------------------------------------------------inline CTemporaryCountingStream::operator TStream*(){	return fStream;}//----------------------------------------------------------------------------------------inline TStream* CTemporaryHandleStream::GetStream(){	return fStream;}//----------------------------------------------------------------------------------------inline CTemporaryHandleStream::operator Handle(){	return fHandle;}//----------------------------------------------------------------------------------------inline CTemporaryHandleStream::operator TStream*(){	return fStream;}#endif